    /// <summary>Brand colours that are near black or very dark vanish on a dark surface; lift them until they read.</summary>
    public static Color Visible(Color color)
    {
        var mixed = color;
        for (var step = 1; step <= 10 && Luminance(mixed) < 0.2; step++)
        {
            var t = step / 10.0;
            mixed = Color.FromRgb(
                (byte)(color.R + (255 - color.R) * t),
                (byte)(color.G + (255 - color.G) * t),
                (byte)(color.B + (255 - color.B) * t));
        }
        return mixed;
    }

    private static double Luminance(Color c)
    {
        static double Channel(byte value)
        {
            var s = value / 255.0;
            return s <= 0.03928 ? s / 12.92 : Math.Pow((s + 0.055) / 1.055, 2.4);
        }
        return 0.2126 * Channel(c.R) + 0.7152 * Channel(c.G) + 0.0722 * Channel(c.B);
    }

    /// <summary>The name a person would write: "Node.js", ".NET SDK", "JDK".</summary>
    public static string Title(ToolKind tool) => tool switch
    {
        ToolKind.Node => "Node.js",
        ToolKind.Jdk => "JDK",
        ToolKind.DotNetSdk => ".NET SDK",
        ToolKind.Rustc => "Rust",
        ToolKind.Php => "PHP",
        ToolKind.Cmake => "CMake",
        ToolKind.Npm or ToolKind.Pnpm or ToolKind.Uv => ToolKinds.Display(tool),
        _ => char.ToUpperInvariant(ToolKinds.Display(tool)[0]) + ToolKinds.Display(tool)[1..]
    };

    public static bool HasLogo(ToolKind tool) => Logos.ContainsKey(tool);

    public static Color ColorOf(ToolKind tool) =>
        Logos.TryGetValue(tool, out var logo) ? Visible(Color.Parse("#" + logo.Hex)) : Palette.TextDim;

    /// <summary>A square tile with the tool's logo (or its first letter) at the given size.</summary>
    public static Border Tile(ToolKind tool, double size = 28)
    {
        var color = ColorOf(tool);
        Control glyph;
        if (Logos.TryGetValue(tool, out var logo))
        {
            glyph = new Avalonia.Controls.Shapes.Path
            {
                Data = StreamGeometry.Parse(logo.Path),
                Fill = Palette.Brush(color),
                Stretch = Stretch.Uniform,
                Width = size * 0.58,
                Height = size * 0.58
            };
        }
        else
        {
            glyph = new TextBlock
            {
                Text = ToolKinds.Display(tool)[..1].ToUpperInvariant(),
                FontSize = size * 0.46,
                FontWeight = FontWeight.Bold,
                Foreground = Palette.Brush(color),
                HorizontalAlignment = HorizontalAlignment.Center,
                VerticalAlignment = VerticalAlignment.Center
            };
        }
        return new Border
        {
            Width = size,
            Height = size,
            CornerRadius = new Avalonia.CornerRadius(size * 0.28),
            Background = new SolidColorBrush(color, 0.14),
            VerticalAlignment = VerticalAlignment.Center,
            Child = glyph
        };
    }
}